def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add the last field if we're not at the start
            if i > 0 or len(fields) == 0:
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that next character is comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        # Skip the comma if present
                        if i < len(line):
                            i += 1
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field - runs until comma or end of line
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            # Skip the comma if present
            if i < len(line):
                i += 1

    return fields

